import java.util.Locale;

private static String[] copyStrings(final String[] src) {
    if (src == null) {
        return null;
    }
    String[] dst = new String[src.length];
    for (int i = 0; i < src.length; i++) {
        String s = src[i];
        dst[i] = (s == null) ? null : s.toLowerCase(Locale.ROOT);
    }
    return dst;
}

